import { glob as realGlob, GlobOptions } from "glob";
import type { FileSystem } from "@servicenow/sdk-build-core";
import { RollupFsAdapter } from "../rollup/rollup-fs-adapter";

interface GlobOptionsWithFluentFs extends Omit<GlobOptions, "fs"> {
  fs: FileSystem;
}

export function glob(
  pattern: string | string[],
  options: GlobOptionsWithFluentFs,
) {
  if (!options.fs) {
    throw new Error("The 'fs' option is required for glob.");
  }
  const normalizedPattern = Array.isArray(pattern)
    ? pattern.map((p) => p.replace(/\\/g, "/"))
    : pattern.replace(/\\/g, "/");
  return realGlob(normalizedPattern, {
    ...options,
    fs: new RollupFsAdapter(options.fs),
    platform: process.platform,
  });
}
